-- NEWER VGM Other Games — Intelligent Systems (publisher section)
--
-- Source: reference/NEWER VGM Sound Sources - Other Games.csv lines 7584-8011.
-- 21 game records, ~380 usage rows.
--
-- Second batch from the "Other Games" file. Intelligent Systems is
-- composer-dense (Yuka Tsujiyoko anchors most early FE + Battle Clash,
-- Yoshito Hirano anchors Advance Wars 2 onward + mid-series FE) and
-- evolves from Roland U-220 / SOUND Canvas era (1992-2007 SNES through
-- Wii) to EastWest Symphonic Orchestra + Heavyocity Damage + Vienna
-- Symphonic Library era (2012-2023 3DS through Switch).
--
-- Composer credits (from in-CSV "(Music by:" notes):
--   - Battle Clash, FE Mystery of the Emblem, FE Genealogy, FE Thracia 776,
--     FE Binding Blade — Yuka Tsujiyoko
--   - Metal Combat: Falcon's Revenge — Yuka Tsujiyoko, Kenichi Nishimaki,
--     Masaya Kuzume
--   - Super Famicom Wars — Kenichi Nishimaki
--   - Advance Wars — Taishi Senda
--   - FE Blazing Blade — Yuka Tsujiyoko, Saki Haruyama
--   - Advance Wars 2, Dual Strike, Days of Ruin, Path of Radiance (+others),
--     Radiant Dawn (+others) — Yoshito Hirano (anchor)
--   - FE Sacred Stones — composer NULL (no in-CSV credit)
--   - FE Awakening, Fates, Heroes, Echoes, Three Houses, Engage —
--     Hiroki Morishita + Rei Kondoh era (varied collaborators)
--
-- New manufacturers introduced this batch:
--   - Stems: Jill                  (cross-media reference convention —
--                                    FE Engage row T7956 quotes "Stems: Jill"
--                                    extracting Violent Strings from FE Heroes)
--   - Synthogy                     (Ivory II pianos)
--   - Xfer Records                 (Serum synth)
--
-- New products this batch (selection — INSERT OR IGNORE on all):
--   - AKAI S1000
--   - KORG X5
--   - Roland SOUND Canvas SC-8850, SR-JV80-01
--   - Best Service XX-Large Club Edition 4
--   - Best Service ProSamples Vol. 8 (World Vocals), Vol. 11 (Classic
--     Orchestra), Vol. 12 (Dance Vocals), Vol. 13 (Choirs), Vol. 42
--     (Session Instruments)
--   - Best Service Ethno World Voices (distinct from existing
--     Ethno World Instruments per Rule 2)
--   - Best Service Advanced Orchestra Extended Edition (distinct from
--     existing "Advanced Orchestra" and "Advanced Orchestra Extended")
--   - Best Service Studio Box Mark III
--   - EastWest Dance/Industrial II (distinct from existing Dance/Industrial)
--   - EastWest ProSamples Vol. 20 (Orchestral Brass), Vol. 31 (Rare Ethnic
--     Instruments)
--   - EastWest Voices of the Apocalypse
--   - Big Fish Audio Celtic Instruments
--   - Heavyocity Damage (existing) — new path "01 Rhythmic Suites ->
--     Loop Menus" + "02 Percussive Kits -> 05 Damage Kits"
--   - Native Instruments Intakt Factory Library, Rise and Hit, Rise & Hit,
--     FM8 (existing)
--   - Spectrasonics Omnisphere 2 (distinct from existing Omnisphere
--     per Rule 2)
--   - Spitfire Audio Symphonic Woodwinds (existing)
--   - Steinberg Halion Sonic SE
--   - Synthogy Ivory II, Ivory II Pianos
--   - Ueberschall ProSamples Vol. 45 (Techno ID)
--   - UltimateSoundBank Soundscan Vol. 23 (Historical Instruments),
--     Raricussions
--   - Vienna Symphonic Library Full Set Pro (distinct from existing
--     Special Edition Vol. 1 per Rule 2)
--   - Xfer Records Serum
--   - Yellow Tools ProSamples Vol. 43 (Real Drum Kits)
--   - Zero-G Twisted City, ProSamples Vol. 8 / 21 / 23 / 47
--
-- Verbatim preservations (Rule 2):
--   - "Fire Emblem: Monshō no Nazo (Mystery of the Emblem)" — Japanese
--     title with macron + Western subtitle preserved verbatim in title.
--   - "Fire Emblem: Seisen no Keifu (Genaelogy of the Holy War)" —
--     contributor misspelling "Genaelogy" (should be Genealogy)
--     preserved verbatim, flagged in notes.
--   - "Sample: Fire Emblem: Three Houses - Paths That Will Never Cross"
--     and "Sample: Fire Emblem Heroes - Strike ~ Heroes Version"
--     (FE Heroes row T7907-7908) — intra-series sample references,
--     raw_source pattern.
--   - "Stems: Jill - Fire Emblem Heroes" (FE Engage row T7956) —
--     novel "Stems: <person>" cross-media pattern where Jill extracted
--     stems from FE Heroes. Manufacturer-style attribution per Rule 2.
--   - "Feburary 2, 2017" misspelling (FE Heroes release date row 7906)
--     — date normalised to 2017-02-02 in released column.
--   - Track names with curly/non-ASCII chars (Fódlan, ~Used throughout
--     the soundtrack~, "Chapter 1 ""The Girl from the Spirit-Forest""")
--     preserved with SQL double-quote escaping where applicable.

INSERT OR IGNORE INTO manufacturers (name) VALUES
  ('Stems: Jill'),
  ('Synthogy'),
  ('Xfer Records');

